/**
 * Procedural model factories (Model.factory): TypeScript files under models/ that export
 * `create<Name>Model(options): THREE.Group`, as generated by img2threejs. The main process compiles
 * each one to a browser module served at game-models/<path>.js (Play, preview, editor, web export).
 * See docs/specs/SPEC-Img2ThreeJS-Agent.md.
 */

export const FACTORY_SOURCE_DIR = 'models'
export const COMPILED_FACTORIES_DIR = 'game-models'

const FACTORY_EXT = /\.(ts|mts|js|mjs)$/

/** A factory source must stay inside models/ and be a TS/JS module */
export function isValidFactorySrc(src: unknown): src is string {
  if (typeof src !== 'string' || !src) return false
  const norm = src.replace(/\\/g, '/')
  if (!norm.startsWith(`${FACTORY_SOURCE_DIR}/`) || norm.split('/').some((seg) => seg === '..' || seg === '' || seg === '.')) return false
  return FACTORY_EXT.test(norm) && !norm.endsWith('.d.ts')
}

/** 'models/mug/createMugModel.ts' -> 'game-models/mug/createMugModel.js' */
export function compiledFactoryPath(src: string): string {
  const rel = src.replace(/\\/g, '/').replace(/^\.?\//, '').replace(new RegExp(`^${FACTORY_SOURCE_DIR}/`), '')
  return `${COMPILED_FACTORIES_DIR}/${rel.replace(FACTORY_EXT, '')}.js`
}

/** 'game-models/mug/createMugModel.js' -> 'models/mug/createMugModel' (no extension), or null */
export function factorySourceStem(compiledRel: string): string | null {
  const norm = compiledRel.replace(/\\/g, '/').replace(/^\/+/, '')
  if (!norm.startsWith(`${COMPILED_FACTORIES_DIR}/`) || !norm.endsWith('.js')) return null
  const stem = norm.slice(COMPILED_FACTORIES_DIR.length + 1, -3)
  if (!stem || stem.split('/').some((seg) => seg === '..' || seg === '' || seg === '.')) return null
  return `${FACTORY_SOURCE_DIR}/${stem}`
}

const FACTORY_EXPORT = /^create\w+Model$/

/** Names of exports that look like a model factory */
export function factoryExportNames(mod: Record<string, unknown>): string[] {
  return Object.keys(mod).filter((k) => FACTORY_EXPORT.test(k) && typeof mod[k] === 'function')
}

/** The factory function: the named export, or the only create<Name>Model export */
export function pickFactoryExport(mod: Record<string, unknown>, name?: string): { fn: (options?: Record<string, unknown>) => unknown; name: string } | { error: string } {
  if (name) {
    const fn = mod[name]
    if (typeof fn !== 'function') return { error: `Export "${name}" tidak ada atau bukan fungsi` }
    return { fn: fn as any, name }
  }
  const names = factoryExportNames(mod)
  if (names.length === 1) return { fn: mod[names[0]] as any, name: names[0] }
  if (names.length === 0) return { error: 'Tidak ada export create<Nama>Model di file factory' }
  return { error: `Lebih dari satu export factory (${names.join(', ')}); isi factoryExport` }
}

/** Options Linden passes to every factory call */
export interface FactoryCallOptions {
  castShadow?: boolean
  receiveShadow?: boolean
  textureSize?: number
  textureAnisotropy?: number
  qualityPriority?: 'reference-fidelity' | 'balanced'
}
